import { NextResponse } from 'next/server'
import { redis } from '@/lib/redis'

export const dynamic = 'force-dynamic'
export const revalidate = 0

/** A viewer is "here" for this long after their last ping. */
const PRESENCE_TTL_MS = 30_000
const PRESENCE_KEY = 'portfolio:presence'
const VIEWS_KEY = 'portfolio:views'

/** Session ids are generated by the browser; never trust their shape. */
const ID = /^[a-z0-9]{8,40}$/

/**
 * Live presence and the lifetime view count.
 *
 * Presence is a sorted set scored by the time of each viewer's last ping.
 * Every request drops the entries that have gone stale and then counts
 * what is left, so a viewer who closes the tab disappears within
 * PRESENCE_TTL_MS without needing to tell us they left. That is four
 * cheap commands per ping and no background job.
 *
 * Nothing stored identifies anybody: the id is a random string the
 * browser makes up for the tab and forgets when it closes. No IP, no
 * cookie, no fingerprint.
 */
export async function POST(request: Request) {
  if (!redis) {
    return NextResponse.json({ available: false }, { status: 503 })
  }

  let id: unknown
  let first = false
  try {
    const body = await request.json()
    id = body?.id
    first = body?.first === true
  } catch {
    return NextResponse.json({ error: 'bad request' }, { status: 400 })
  }

  if (typeof id !== 'string' || !ID.test(id)) {
    return NextResponse.json({ error: 'bad id' }, { status: 400 })
  }

  const now = Date.now()

  try {
    const pipeline = redis.pipeline()
    pipeline.zadd(PRESENCE_KEY, { score: now, member: id })
    pipeline.zremrangebyscore(PRESENCE_KEY, 0, now - PRESENCE_TTL_MS)
    pipeline.zcard(PRESENCE_KEY)
    // Counted once per tab, on that tab's first ping.
    if (first) pipeline.incr(VIEWS_KEY)
    else pipeline.get(VIEWS_KEY)

    const results = await pipeline.exec()
    const viewing = Number(results[2] ?? 1)
    const views = Number(results[3] ?? 0)

    return NextResponse.json(
      { available: true, viewing: Math.max(viewing, 1), views },
      { headers: { 'Cache-Control': 'no-store' } }
    )
  } catch {
    // A Redis hiccup must never surface on the page.
    return NextResponse.json({ available: false }, { status: 503 })
  }
}
